import{_ as s,a0 as o,w as a,s as p,ao as u,I as l,x as t,a1 as i,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const I=JSON.parse('{"title":"Kubernetes 架構指南 | LCTT x X-CMD","titleTemplate":false,"description":"Kubernetes 架構指南 | LCTT (202207) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Kubernetes 架構指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Kubernetes 架構指南 | LCTT (202207) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202207/20220214 A guide to Kubernetes architecture","title":"Kubernetes 架構指南","tag":"202207","desc":""},"relativePath":"202207/20220214 A guide to Kubernetes architecture.md","filePath":"[post].md"}'),d={name:"202207/20220214 A guide to Kubernetes architecture.md"};function b(m,e,f,P,A,T){const r=o("Link");return a(),p("div",null,[e[40]||(e[40]=u('<h1 id="kubernetes-架構指南" tabindex="-1">Kubernetes 架構指南 <a class="header-anchor" href="#kubernetes-架構指南" aria-label="Permalink to “Kubernetes 架構指南”">​</a></h1><blockquote><p>瞭解 Kubernetes 架構中不同組件是如何組合在一起的，這樣你就可以更好地排查問題、維護一個健康的集羣，以及優化工作流。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202207/03/105135ey33hhx022m9y9fr.jpg" alt=""></p><p>使用 Kubernetes 來編排容器，這種描述説起來簡單，但理解它的實際含義以及如何實現它完全是另外一回事。如果你正在運行或管理 Kubernetes 集羣，那麼你就會知道 Kubernetes 由一台稱為 “<ruby>控制平面<rt>control plane</rt></ruby>” 的機器和許多其他 <ruby>工作節點<rt>worker node</rt></ruby> 機器組成。每種類型都有一個複雜但穩定的堆棧，這使編排成為可能，熟悉每個組件有助於理解它是如何工作的。</p><p><img src="https://opensource.com/sites/default/files/uploads/kubernetes-architecture-diagram.png" alt="Kubernetes 架構圖" title="Kubernetes architecture diagram"></p>',5)),l("p",null,[l("em",null,[e[1]||(e[1]=t("（Nived Velayudhan, ",-1)),i(r,{href:"https://creativecommons.org/licenses/by-sa/4.0/"},{default:n(()=>[...e[0]||(e[0]=[t("CC BY-SA 4.0",-1)])]),_:1}),e[2]||(e[2]=t("）",-1))])]),e[41]||(e[41]=u('<h3 id="控制平面組件" tabindex="-1">控制平面組件 <a class="header-anchor" href="#控制平面組件" aria-label="Permalink to “控制平面組件”">​</a></h3><p>Kubernetes 安裝在一個稱為“<ruby>控制平面<rt>control plane</rt></ruby>”的機器上，它會運行 Kubernetes 守護進程，並在啓動容器和<ruby>容器組<rt>pod</rt></ruby>時與之通信。下面介紹控制平面的各個組件。</p><h4 id="etcd" tabindex="-1">etcd <a class="header-anchor" href="#etcd" aria-label="Permalink to “etcd”">​</a></h4><p>etcd 是一種快速、分佈式一致性鍵值存儲器，用作 Kubernetes 對象數據的持久存儲，如容器組、副本控制器、密鑰和服務。etcd 是 Kubernetes 存儲集羣狀態和元數據的唯一地方。唯一與 etcd 直連的組件是 Kubernetes API 服務器。其他所有組件都通過 API 服務器間接的從 etcd 讀寫數據。</p><p>etcd 還實現了一個監控功能，它提供了一個基於事件的接口，用於異步監控鍵的更改。一旦你更改了一個鍵，它的監控者就會收到通知。API 服務器組件嚴重依賴於此來獲得通知，並將 etcd 變更至期望狀態。</p><p><em>為什麼 etcd 實例的數量應該是奇數？</em></p>',6)),l("p",null,[e[4]||(e[4]=t("你通常會運行三個、五個或七個 etcd 實例實現高可用（HA）環境，但這是為什麼呢？因為 etcd 是分佈式數據存儲，可以水平擴展它，但你需要確保每個實例中的數據是一致的。因此，需要為系統當前狀態達成共識，etcd 為此使用 ",-1)),i(r,{href:"https://www.geeksforgeeks.org/raft-consensus-algorithm/"},{default:n(()=>[...e[3]||(e[3]=[t("RAFT 共識算法",-1)])]),_:1}),e[5]||(e[5]=t("。",-1))]),e[42]||(e[42]=l("p",null,"RAFT 算法需要經過選舉（或仲裁）集羣才能進入下一個狀態。如果你只有兩個 etcd 實例並且他們其中一個失敗的話，那麼 etcd 集羣無法轉換到新的狀態，因為不存在過半這個概念。如果你有三個 etcd 實例，一個實例可能會失敗，但仍有 2 個實例可用於進行選舉。",-1)),e[43]||(e[43]=l("h4",{id:"api-服務器",tabindex:"-1"},[t("API 服務器 "),l("a",{class:"header-anchor",href:"#api-服務器","aria-label":"Permalink to “API 服務器”"},"​")],-1)),e[44]||(e[44]=l("p",null,"API 服務器是 Kubernetes 中唯一直接與 etcd 交互的組件。Kubernetes 中的其他所有組件都必須通過 API 服務器來處理集羣狀態，包括客户端（kubectl）。API 服務器具有以下功能：",-1)),l("ul",null,[e[12]||(e[12]=l("li",null,"提供在 etcd 中存儲對象的一致方式。",-1)),e[13]||(e[13]=l("li",null,"執行驗證對象，防止客户端存儲配置不正確的對象（如果它們直接寫入 etcd 數據存儲，可能會發生這種情況）。",-1)),e[14]||(e[14]=l("li",null,"提供 RESTful API 來創建、更新、修改或刪除資源。",-1)),l("li",null,[e[7]||(e[7]=t("提供 ",-1)),i(r,{href:"https://stackoverflow.com/questions/52910322/kubernetes-resource-versioning#:~:text=Optimistic%20concurrency%20control%20(sometimes%20referred,updated%2C%20the%20version%20number%20increases."},{default:n(()=>[...e[6]||(e[6]=[t("樂觀併發鎖",-1)])]),_:1}),e[8]||(e[8]=t("，在發生更新時，其他客户端永遠不會有機會重寫對象。",-1))]),e[15]||(e[15]=l("li",null,"對客户端發送的請求進行身份驗證和授權。它使用插件提取客户端的用户名、ID、所屬組，並確定通過身份驗證的用户是否可以對請求的資源執行請求的操作。",-1)),l("li",null,[e[10]||(e[10]=t("如果請求試圖創建、修改或刪除資源，則負責 ",-1)),i(r,{href:"https://kubernetes.io/docs/reference/access-authn-authz/admission-controllers/"},{default:n(()=>[...e[9]||(e[9]=[t("權限控制",-1)])]),_:1}),e[11]||(e[11]=t("。例如，AlwaysPullImages、DefaultStorageClass 和 ResourceQuota。",-1))]),e[16]||(e[16]=l("li",null,"實現了一種監控機制（類似於 etcd），用户客户端監控更改。這允許調度器和控制器管理器等組件以松耦合的方式與 API 服務器交互。",-1))]),e[45]||(e[45]=u('<h4 id="控制器管理器" tabindex="-1">控制器管理器 <a class="header-anchor" href="#控制器管理器" aria-label="Permalink to “控制器管理器”">​</a></h4><p>在 Kubernetes 中，控制器持續監控集羣狀態，然後根據需要進行或請求更改。每個控制器都嘗試將當前集羣狀態變更至期望狀態。控制器至少跟蹤一種 Kubernetes 資源類型，這些對象均有一個字段來表示期望的狀態。</p><p>控制器示例：</p><ul><li>副本管理器（管理<ruby>副本控制器<rt>ReplicationController</rt></ruby>資源的控制器）</li><li><ruby>副本集<rt>ReplicaSet</rt></ruby>、<ruby>守護進程集<rt>DaemonSet</rt></ruby> 和任務控制器</li><li>部署控制器</li><li>有狀態負載控制器</li><li>節點控制器</li><li>服務控制器</li><li>接入點控制器</li><li>命名空間控制器</li><li><ruby>持久卷<rt>PersistentVolume</rt></ruby>控制器</li></ul><p>控制器通過監控機制來獲得變更通知。它們監視 API 服務器對資源的變更，對每次更改執行操作，無論是新建對象還是更新或刪除現有對象。大多數時候，這些操作包括創建其他資源或更新監控的資源本身。不過，由於使用監控並不能保證控制器不會錯過任何事件，它們還會定期執行一系列操作，確保沒有錯過任何事件。</p>',5)),l("p",null,[e[19]||(e[19]=t("控制器管理器還執行生命週期功能。例如命名空間創建和生命週期、事件垃圾收集、已終止容器組垃圾收集、",-1)),i(r,{href:"https://kubernetes.io/docs/concepts/architecture/garbage-collection/"},{default:n(()=>[...e[17]||(e[17]=[t("級聯刪除垃圾收集",-1)])]),_:1}),e[20]||(e[20]=t(" 和節點垃圾收集。有關更多信息，參考 ",-1)),i(r,{href:"https://kubernetes.io/docs/concepts/architecture/cloud-controller/"},{default:n(()=>[...e[18]||(e[18]=[t("雲控制器管理器",-1)])]),_:1}),e[21]||(e[21]=t("。",-1))]),e[46]||(e[46]=u('<h4 id="調度器" tabindex="-1">調度器 <a class="header-anchor" href="#調度器" aria-label="Permalink to “調度器”">​</a></h4><p>調度器是一個將容器組分配給節點的控制平面進程。它會監視新創建沒有分配節點的容器組。調度器會給每個發現的容器組分配運行它的最佳節點。</p><p>滿足容器組調度要求的節點稱為可調度節點。如果沒有合適的節點，那麼容器組會一直處於未調度狀態，直到調度器可以安置它。一旦找到可調度節點，它就會運行一組函數來對節點進行評分，並選擇得分最高的節點，然後它會告訴 API 服務器所選節點的信息。這個過程稱為綁定。</p><p>節點的選擇分為兩步：</p><ol><li>過濾所有節點的列表，獲得可以調度容器組的節點列表（例如，PodFitsResources 過濾器檢查候選節點是否有足夠的可用資源來滿足容器組的特定資源請求）。</li><li>對第一步得到的節點列表進行評分和排序，選擇最佳節點。如果得分最高的有多個節點，循環過程可確保容器組會均勻地部署在所有節點上。</li></ol><p>調度決策要考慮的因素包括：</p><ul><li>容器組是否請求硬件/軟件資源？節點是否報告內存或磁盤壓力情況？</li><li>節點是否有與容器組規範中的節點選擇器匹配的標籤？</li><li>如果容器組請求綁定到特定地主機端口，該端口是否可用？</li><li>容器組是否容忍節點的污點？</li><li>容器組是否指定節點親和性或反親和性規則？</li></ul><p>調度器不會指示所選節點運行容器組。調度器所做的就是通過 API 服務器更新容器組定義。然後 API 服務器通過監控機制通知 kubelet 容器組已被調度，然後目標節點上的 kubelet 服務看到容器組被調度到它的節點，它創建並運行容器組。</p><h3 id="工作節點組件" tabindex="-1">工作節點組件 <a class="header-anchor" href="#工作節點組件" aria-label="Permalink to “工作節點組件”">​</a></h3><p>工作節點運行 kubelet 代理，這允許控制平面接納它們來處理負載。與控制平面類似，工作節點使用幾個不同的組件來實現這一點。 以下部分描述了工作節點組件。</p><h4 id="kubelet" tabindex="-1">Kubelet <a class="header-anchor" href="#kubelet" aria-label="Permalink to “Kubelet”">​</a></h4><p>Kubelet 是一個運行在集羣中每個節點上的代理，負責在工作節點上運行的所有事情。它確保容器在吊艙中運行。</p><p>kubelet服務的主要功能有：</p><ul><li>通過在 API 服務器中創建節點資源來註冊它正在運行的節點。</li><li>持續監控 API 服務器上調度到節點的容器組。</li><li>使用配置的容器運行時啓動容器組的容器。</li><li>持續監控正在運行的容器，並將其狀態、事件和資源消耗報告給 API 服務器。</li><li>運行容器存活探測，在探測失敗時重啓容器，當 API 服務器中刪除容器組時終止（通知服務器容器組終止的消息）。</li></ul><h4 id="服務代理" tabindex="-1">服務代理 <a class="header-anchor" href="#服務代理" aria-label="Permalink to “服務代理”">​</a></h4><p>服務代理（kube-proxy）在每個節點上運行，確保一個容器組可以與另一個容器組通訊，一個節點可以與另一個節點對話，一個容器可以與另一個容器對話。它負責監視 API 服務器對服務和容器組定義的更改，以保持整個網絡配置是最新的。當一項服務得到多個容器組的支持時，代理會在這些容器組之間執行負載平衡。</p><p>kube-proxy 之所以叫代理，是因為它最初實際上是一個代理服務器，用於接受連接並將它們代理到容器組。當前的實現是使用 iptables 規則將數據包重定向到隨機選擇的後端容器組，而無需通過實際的代理服務器。</p><p>關於它工作原理的高級視圖：</p><ul><li>當你創建一個服務時，會立即分配一個虛擬 IP 地址。</li><li>API 服務器會通知在工作節點上運行的 kube-proxy 代理有一個新服務。</li><li>每個 kube-proxy 通過設置 iptables 規則使服務可尋址，確保截獲每個服務 IP/端口對，並將目的地址修改為支持服務的一個容器組。</li><li>監控 API 服務器對服務或其端點對象的更改。</li></ul><h4 id="容器運行時" tabindex="-1">容器運行時 <a class="header-anchor" href="#容器運行時" aria-label="Permalink to “容器運行時”">​</a></h4><p>容器運行時有兩類：</p><ul><li><strong>較低級別的容器運行時：</strong> 它們主要關注運行中的容器併為容器設置命名空間和<ruby>控制組<rt>cgroup</rt></ruby>。</li><li><strong>更高級別的容器運行時（容器引擎）：</strong> 它們專注于格式、解包、管理、共享鏡像以及為開發人員提供 API。</li></ul><p>容器運行時負責：</p><ul><li>如果容器鏡像本地不存在，則從鏡像倉庫中提取。</li><li>將鏡像解壓到寫時複製文件系統，所有容器層疊加創建一個合併的文件系統。</li><li>準備一個容器掛載點。</li><li>設置容器鏡像的元數據，如覆蓋命令、用户輸入的入口命令，並設置 SECCOMP 規則，確保容器按預期運行。</li><li>通知內核將進程、網絡和文件系統等隔離分配給容器。</li><li>通知內核分配一些資源限制，如 CPU 或內存限制。</li><li>將系統調用（syscall）傳遞給內核啓動容器。</li><li>確保 SElinux/AppArmor 設置正確。</li></ul><h3 id="協同" tabindex="-1">協同 <a class="header-anchor" href="#協同" aria-label="Permalink to “協同”">​</a></h3>',25)),l("p",null,[e[23]||(e[23]=t("系統級組件協同工作，確保 Kubernetes 集羣的每個部分都能實現其目和執行其功能。當你深入編輯 ",-1)),i(r,{href:"https://www.redhat.com/sysadmin/yaml-beginners"},{default:n(()=>[...e[22]||(e[22]=[t("YAML 文件",-1)])]),_:1}),e[24]||(e[24]=t(" 時，有時很難理解請求是如何在集羣中通信的。現在你已經瞭解了各個部分是如何組合在一起的，你可以更好地理解 Kubernetes 內部發生了什麼，這有助於診斷問題、維護健康的集羣並優化你的工作流。",-1))]),e[47]||(e[47]=l("hr",null,null,-1)),l("p",null,[e[26]||(e[26]=t("via: ",-1)),i(r,{href:"https://opensource.com/article/22/2/kubernetes-architecture"},{default:n(()=>[...e[25]||(e[25]=[t("https://opensource.com/article/22/2/kubernetes-architecture",-1)])]),_:1})]),l("p",null,[e[31]||(e[31]=t("作者：",-1)),i(r,{href:"https://opensource.com/users/nivedv"},{default:n(()=>[...e[27]||(e[27]=[t("Nived Velayudhan",-1)])]),_:1}),e[32]||(e[32]=t(" 選題：",-1)),i(r,{href:"https://github.com/lujun9972"},{default:n(()=>[...e[28]||(e[28]=[t("lujun9972",-1)])]),_:1}),e[33]||(e[33]=t(" 譯者：",-1)),i(r,{href:"https://github.com/MjSeven"},{default:n(()=>[...e[29]||(e[29]=[t("MjSeven",-1)])]),_:1}),e[34]||(e[34]=t(" 校對：",-1)),i(r,{href:"https://github.com/turbokernel"},{default:n(()=>[...e[30]||(e[30]=[t("turbokernel",-1)])]),_:1})]),l("p",null,[e[37]||(e[37]=t("本文由 ",-1)),i(r,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[35]||(e[35]=[t("LCTT",-1)])]),_:1}),e[38]||(e[38]=t(" 原創編譯，",-1)),i(r,{href:"https://linux.cn/"},{default:n(()=>[...e[36]||(e[36]=[t("Linux中國",-1)])]),_:1}),e[39]||(e[39]=t(" 榮譽推出",-1))])])}const y=s(d,[["render",b]]);export{I as __pageData,y as default};
